mapper.select:
SELECT USER_ID, USER_NM, EMAIL, FAILED_CNT, LOCK_YN, USE_YN, REGIST_DT FROM APP_USER
AND (USER_ID LIKE '%' || #{searchKeyword} || '%' OR USER_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
UPDATE APP_USER
SET FAILED_CNT = COALESCE(FAILED_CNT, 0) + 1
WHERE USER_ID = #{userId}
